function buildRects(
  validBreaks: readonly Day[],
  systemBreaks: readonly Day[],
  valueAt: (vi: number, si: number) => CellValue,
): Rect[] {
  const rows: Run[][] = []
  for (let j = 0; j < systemBreaks.length - 1; j++) {
    const runs: Run[] = []
    for (let i = 0; i < validBreaks.length - 1; i++) {
      const v = valueAt(i, j)
      if (v === SKIP) continue
