  let i = 0
  while (i < rows.length) {
    const runs = rows[i]!
    let j = i + 1
    while (j < rows.length && runsEqual(rows[j]!, runs)) j++
    const systemFrom = systemBreaks[i]!
    const systemTo = systemBreaks[j]!
